  package   org . simmetrics . metrics ;   import   java . util . ArrayList ;  import   java . util . List ;  import   org . simmetrics . ListMetric ;   public class SimonWhite  <  T >  implements   ListMetric  < T >  {    @ Override public  float compare  (   List  < T > a ,   List  < T > b )  {  if  (   a . isEmpty  ( ) ||  b . isEmpty  ( ) )  {  return 0.0f ; }   b =  new  ArrayList  < >  ( b ) ;   int  union =   a . size  ( ) +  b . size  ( ) ;   int  intersection = 0 ;  for ( T token : a )  {  if  (  b . remove  ( token ) )  {   intersection ++ ; } }  return   2.0f * intersection / union ; }    @ Override public String toString  ( )  {  return "SimonWhite" ; } }